export function sameOrigin(req) {
  try{const origin=new URL(req.headers.origin);return ['https:','http:'].includes(origin.protocol)&&origin.host===req.headers.host;}catch{return false;}
}
async function body(req,limit=131072) {
  let text='';for await(const part of req){text+=part;if(Buffer.byteLength(text)>limit)throw Object.assign(new Error('Request too large'),{status:413});}
