  if(tail==='inbounds/ui.js'&&req.method==='GET'){file(res,'inbounds-ui.js','text/javascript; charset=utf-8');return;}
  if(tail==='brand.js'&&req.method==='GET'){file(res,'brand.js','text/javascript; charset=utf-8');return;}
  if(tail==='hashem/ui.js'&&req.method==='GET'){file(res,'hashem-ui.js','text/javascript; charset=utf-8');return;}
  if(tail==='bot/ui.js'&&req.method==='GET'){file(res,'bot-ui.js','text/javascript; charset=utf-8');return;}
  if(tail==='hashem/source.tar.gz'&&req.method==='GET'){const data=Buffer.from(readFileSync(join(HERE,'hashem-source.tar.b64'),'utf8'),'base64');res.writeHead(200,{'content-type':'application/gzip','content-disposition':'attachment; filename=alirezaserver-hashem-source.tar.gz','cache-control':'public, max-age=300','x-content-type-options':'nosniff'});res.end(data);return;}
  if((tail==='bot/source.tar.gz'||tail==='bot/web/source.tar.gz')&&req.method==='GET'){const data=Buffer.from(readFileSync(join(HERE,'alirezabot-source.tar.b64'),'utf8'),'base64');res.writeHead(200,{'content-type':'application/gzip','content-disposition':'attachment; filename=alirezabot-source.tar.gz','cache-control':'public, max-age=300','x-content-type-options':'nosniff'});res.end(data);return;}
  if(tail.startsWith('bot/web/')){await phpProxy(req,res,req.url.slice(req.url.indexOf('/alireza/bot/web/')+17),base+'/alireza/bot/web/');return;}
  if(tail.startsWith('bot/sub/')&&req.method==='GET'){const url=await botBridge(req,base).subscription(tail.slice(8));if(!url){json(res,404,{error:'Invalid subscription'});return;}res.writeHead(302,{'location':url,'cache-control':'no-store','referrer-policy':'no-referrer'});res.end();return;}
  if(tail.startsWith('api/bot-bridge/')){if(!botAuthorized(req)){json(res,403,{success:false,msg:'Forbidden'});return;}try{const result=await botBridge(req,base).request('/'+tail.slice(15),req.method,['POST','PUT'].includes(req.method)?await body(req):{});json(res,200,result);}catch(e){json(res,e.status||502,{success:false,msg:e.message});}return;}
  const auth=await whoami(req,base);
  if(!auth){json(res,401,{error:'Sign in to the main panel first.'});return;}
  if(tail==='ai'&&req.method==='GET'){res.writeHead(302,{location:base+'/alireza/ai/','cache-control':'no-store'});res.end();return;}
  const aiRoute=tail==='ai/'||tail==='ai/ui.js'||tail.startsWith('api/ai/');
