<!doctype html><html lang="fa" dir="rtl"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>alirezaserver · AI</title><link rel="stylesheet" href="../assets/font.css"><link rel="stylesheet" href="../assets/theme.css"><script src="../assets/theme.js" data-surface="ai"></script><link rel="stylesheet" href="../assets/extension.css"><link rel="stylesheet" href="../assets/console.css"></head><body><main><header><a class="btn" href="../../">← alirezaserver</a><div><span class="eyebrow">ALIREZASERVER / GEMINI</span><h1>AI</h1><p class="muted" data-t="intro"></p></div><div class="actions"><button id="lang">English</button><button id="settings" data-t="settings"></button></div></header><div class="chat-layout"><aside class="card history"><button id="new" class="primary" data-t="new"></button><h3 data-t="history"></h3><div id="history"></div><p class="hint" data-t="privacy"></p></aside><section class="card chat"><div class="between"><strong id="title">AI</strong><span class="status" id="status" role="status"></span></div><div id="suggestions" class="suggestions"></div><button type="button" id="older" hidden data-t="older"></button><div id="messages" class="messages" aria-live="polite"></div><form id="composer" class="composer"><label for="prompt" data-t="prompt"></label><textarea id="prompt" dir="auto" maxlength="16000" required></textarea><div class="actions"><div class="actions"><button class="primary" id="send" data-t="send"></button><button type="button" id="stop" hidden data-t="stop"></button><button type="button" id="retry" data-t="retry"></button></div><button type="button" id="summary" data-t="summary"></button></div><p class="hint" data-t="advisor"></p></form></section></div><div class="notice" id="notice" role="alert" hidden></div></main><dialog id="config"><div class="between"><h2 data-t="settings"></h2><button id="close">✕</button></div><form id="configform" class="setting-grid"><label id="keylabel"><span data-t="key"></span><input id="key" type="password" autocomplete="new-password" dir="ltr"><span class="hint" data-t="keynote"></span></label><div class="actions"><button id="listmodels" type="button" data-t="models"></button><button id="deletekey" type="button" data-t="deletekey"></button></div><label><span data-t="model"></span><select id="model"></select></label><label><span data-t="tokens"></span><input id="tokens" type="number" min="128" max="32768" value="2048"></label><label><span data-t="rpm"></span><input id="rpm" type="number" min="1" max="120" value="6"></label><button class="primary" id="saveconfig" data-t="save"></button><p id="configmessage" class="notice"></p></form></dialog><script src="ui.js"></script></body></html>
