    if not extensions_ok or not shutil.which('php') or not any(pathlib.Path('/usr/sbin').glob('php-fpm*')) or not shutil.which('mariadb') or not shutil.which('logrotate'):
        run(['apt-get','update'],timeout=180);run(['apt-get','install','-y','php-cli','php-fpm','php-mysql','php-curl','php-mbstring','php-zip','php-gd','php-xml','php-bcmath','mariadb-server','logrotate'],timeout=600)
