    sql="CREATE DATABASE IF NOT EXISTS alirezabot CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci; CREATE USER IF NOT EXISTS 'alirezabot'@'localhost' IDENTIFIED BY '"+dbpass+"'; GRANT ALL ON alirezabot.* TO 'alirezabot'@'localhost';"
    run(['mariadb','--protocol=socket','-u','root'],sql)
    config='''<?php
$request_exec_timeout = 30000;
$dbhost='localhost';$dbname='alirezabot';$usernamedb='alirezabot';
$passworddb=DBPASSWORD;
