    web='[Unit]\nDescription=alirezabot dedicated PHP FastCGI\n'+common+'RuntimeDirectory=alirezabot\nExecStart='+str(fpm)+' --nodaemonize --fpm-config /opt/alirezabot/php-fpm.conf\n[Install]\nWantedBy=multi-user.target\n'
    poll='[Unit]\nDescription=alirezabot Telegram polling\n'+common+'User=alirezabot\nGroup=alirezabot\nWorkingDirectory=/opt/alirezabot\nExecStart=/usr/bin/php /opt/alirezabot/poll.php\n[Install]\nWantedBy=multi-user.target\n'
