     with tar.extractfile(matches[0]) as a,temp.open('wb') as b:shutil.copyfileobj(a,b)
     if hashlib.sha256(temp.read_bytes()).hexdigest()!=entry['binarySHA256'][binary]:raise RuntimeError('CORE_BINARY_CHECKSUM')
     temp.chmod(0o700);temp.replace(dst)
 corelock=json.loads((HERE/'hashem-core-build.json').read_text())
