        echo "  4) Stop Bagher Engine Service"
        echo "  5) Restart Bagher Engine Service"
        echo "  6) View Bagher Service Logs"
        echo "  7) Generate Key & Show Foreign authorized_keys Line"
        echo "  8) Clear Conflicting DNAT Rules"
        echo "  0) Back"
