            4) cli_bagher stop; pause_prompt ;;
            5) cli_bagher restart; pause_prompt ;;
            6) cli_bagher logs; pause_prompt ;;
            7) cli_bagher gen-key; pause_prompt ;;
            8) cli_bagher clear-dnat; pause_prompt ;;
            0) return 0 ;;
            *) echo -e "${RED}[!] Invalid option.${NC}"; sleep 1 ;;
        esac
    done
