const root=process.env.ALIREZA_ROOT||'/var/lib/alirezaserver',file=root+'/hashem-jobs.json';let active=false;let statusPending,statusCache,statusTime=0;
const fail=(code,status=400)=>Object.assign(Error(code),{code,status});
let jobs=[];try{jobs=JSON.parse(readFileSync(file));for(const j of jobs)if(j.status==='running'){j.status='interrupted';j.error='Panel restarted. Inspect service status before retrying.';}}catch(e){jobs=[];if(e.code!=='ENOENT')console.error('Hashem job metadata is unavailable; inspect the restricted state file.');}
function save(){mkdirSync(root,{recursive:true,mode:0o700});writeFileSync(file+'.tmp',JSON.stringify(jobs.slice(0,20)),{mode:0o600});renameSync(file+'.tmp',file);}
export function execute(operation,input={}){return new Promise((resolve,reject)=>{const p=spawn('python3',[fileURLToPath(new URL(['probe','setup-ssh','peer-ports'].includes(operation)?'./hashem-ssh.py':'./hashem-manager.py',import.meta.url))],{stdio:['pipe','pipe','pipe']});let out='';const timer=setTimeout(()=>{p.kill('SIGTERM');reject(fail('HASHEM_OPERATION_TIMEOUT',504));},1200000);p.stdout.on('data',b=>{out+=b;if(out.length>131072)p.kill();});p.stderr.resume();p.on('error',()=>{clearTimeout(timer);reject(fail('HASHEM_PROCESS_UNAVAILABLE',503));});p.on('close',code=>{clearTimeout(timer);try{const r=JSON.parse(out);if(code||r.error)reject(fail(r.error||'HASHEM_OPERATION_FAILED',502));else resolve(r);}catch{reject(fail('HASHEM_OPERATION_FAILED',502));}});p.stdin.end(JSON.stringify({...input,operation}));});}
export async function status(){if(!statusCache||Date.now()-statusTime>1500){statusPending||=execute('status').then(v=>{statusCache=v;statusTime=Date.now();return v;}).finally(()=>{statusPending=null;});await statusPending;}return{...statusCache,busy:active,jobs:jobs.slice(0,20)};}
export function start(operation,input){if(active)throw fail('HASHEM_BUSY',409);if(!['install','setup','ports','restart','watchdog','carrier','backup','restore','remove','benchmark','performance','setup-ssh','peer-ports'].includes(operation))throw fail('HASHEM_INVALID_OPERATION');if(['setup','ports','carrier','performance','remove','restore','setup-ssh','peer-ports'].includes(operation)&&input.confirm!==true)throw fail('HASHEM_CONFIRM_REQUIRED');const job={id:randomBytes(8).toString('hex'),operation,status:'running',started:Date.now()};active=true;statusTime=0;jobs.unshift(job);save();execute(operation,input).then(result=>{job.status='ready';job.finished=Date.now();job.result=result;statusTime=0;}).catch(e=>{job.status='failed';job.finished=Date.now();job.error=e.code||'HASHEM_FAILED';}).finally(()=>{active=false;save();});return job;}
export function command(input){const v={...input};if(!v.token)v.token=randomBytes(24).toString('hex');const data=Buffer.from(JSON.stringify(v)).toString('base64');const hash=readFileSync(new URL('./hashem-install.sha256',import.meta.url),'utf8').trim();if(!/^[a-f0-9]{64}$/.test(hash))throw fail('HASHEM_INSTALLER_CHECKSUM');const path='/root/alirezaserver-hashem-install.sh';return{command:"curl -fL --proto '=https' --tlsv1.2 https://raw.githubusercontent.com/alirezachatgpt97-coder/alirezaserver/main/addon/hashem-install.sh -o "+path+" && printf '%s  %s\\n' '"+hash+"' '"+path+"' | sha256sum -c - && sudo bash "+path+" '"+data+"'",token:v.token};}
