const error=(message,status=400)=>Object.assign(Error(message),{status});
let contracts;
async function normalize(){contracts||=import(pathToFileURL((process.env.ALIREZA_NOVA_DIR||'/opt/nova-node-agent')+'/src/xray/inbounds.mjs'));return(await contracts).normalizeProfile;}
