 if(line.startsWith('vmess://')){const v=JSON.parse(Buffer.from(line.slice(8),'base64'));if(bare(v.add)!==identity.origin||v.sni&&bare(v.sni)!==identity.origin)return line;v.sni=identity.host;if(identity.cdn){v.add=identity.host;if(!v.host||bare(v.host)===identity.origin)v.host=identity.host;}return 'vmess://'+Buffer.from(JSON.stringify(v)).toString('base64');}
 let u;try{u=new URL(line);}catch{return line;}
 if(!['vless:','trojan:'].includes(u.protocol)||bare(u.hostname)!==identity.origin||u.searchParams.get('security')!=='tls')return line;
 const sni=u.searchParams.get('sni');if(sni&&bare(sni)!==identity.origin)return line;
 u.searchParams.set('sni',identity.host);if(identity.cdn){u.hostname=identity.host;if(!u.searchParams.has('host')||bare(u.searchParams.get('host'))===identity.origin)u.searchParams.set('host',identity.host);}return u.toString();
